package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 998244353
const MAX_N int = 2*100000 + 1

func modPow(a, e, mod int64) int64 {
	res := int64(1)
	a %= mod
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(in, &n, &m)

	fac := make([]int64, MAX_N+1)
	facInv := make([]int64, MAX_N+1)

	fac[0] = 1
	for i := 1; i <= MAX_N; i++ {
		fac[i] = fac[i-1] * int64(i) % MOD
	}

	facInv[MAX_N] = modPow(fac[MAX_N], MOD-2, MOD)
	for i := MAX_N; i >= 1; i-- {
		facInv[i-1] = facInv[i] * int64(i) % MOD
	}

	modNCr := func(n, r int) int64 {
		if n < r || n < 0 || r < 0 {
			return 0
		}
		tmp := facInv[n-r] * facInv[r] % MOD
		return tmp * fac[n] % MOD
	}

	var ans int64
	if n-3 > 0 {
		ans = modNCr(m, n-1) * int64(n-2) % MOD
		ans = ans * modPow(2, int64(n-3), MOD) % MOD
	} else {
		ans = modNCr(m, n-1) * int64(n-2) % MOD
	}
	ans %= MOD

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, ans)
	out.Flush()
}

